sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	var gr = {};
		gr.sys_id = current.getUniqueValue();
		gr.employee = current.getValue('employee');
		gr.employee_name = current.getDisplayValue('employee');
		gr.deposit_type = current.getValue('deposit_type');
		gr.deposit_percentage = current.getValue('deposit_percentage');
		gr.deposit_amount = current.deposit_amount.getCurrencyValue();
		gr.active = current.getValue('active');

	var message = new hr_CaseAjax().directDepositValidation(new global.JSON().encode(gr));
	message = JSON.parse(message);
	if (message == true) {
		if (current.deposit_type != 'amount')
			current.deposit_amount = '';
		if (current.deposit_type != 'percentage')
			current.deposit_percentage = '';
		return true;
	}
	if (message == 'conflict')
		gs.addErrorMessage(gs.getMessage("This deposit instruction conflicts with the exisitng direct deposit settings."));
	else
		gs.addErrorMessage(message);

	gs.addErrorMessage(gs.getMessage("Invalid update"));
	current.setAbortAction(true);
	})(current, previous);
